"use client";

import { useEffect } from "react";
import Link from "next/link";
import { AlertCircle } from "lucide-react";

export default function GlobalError({
  error,
  reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Log the error to an error reporting service like Sentry
    console.error("Global Error boundary caught an error:", error);
  }, [error]);

  return (
    <html lang="ro">
      <body className="antialiased bg-[#151614] font-manrope">
        <div className="min-h-screen flex flex-col items-center justify-center p-4 text-center">
          <div className="max-w-md w-full bg-[#1c1d1a] border border-white/10 rounded-2xl p-8 shadow-2xl">
            <div className="w-16 h-16 bg-red-500/10 rounded-full flex items-center justify-center mx-auto mb-6">
              <AlertCircle className="w-8 h-8 text-red-500" />
            </div>
            <h1 className="text-2xl md:text-3xl font-playfair font-semibold text-white mb-4">
              Eroare Critică
            </h1>
            <p className="text-gray-400 mb-8">
              Am întâmpinat o problemă server-side și nu am putut încărca aplicația.
              Echipa noastră tehnică a fost notificată.
            </p>

            <div className="flex flex-col gap-4">
              <button
                onClick={() => reset()}
                className="w-full bg-[#E5D3B3] text-black font-semibold py-4 px-6 rounded-xl hover:bg-[#D4C2A2] transition-all"
              >
                Reîncarcă Aplicația
              </button>
              
              <Link
                href="/"
                className="w-full bg-white/5 border border-white/10 text-white font-semibold py-4 px-6 rounded-xl hover:bg-white/10 transition-all"
              >
                Înapoi la Pagina Principală
              </Link>
            </div>
          </div>
        </div>
      </body>
    </html>
  );
}
